package flameshot

import (
	"bytes"
	"context"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"time"
)

const (
	defaultHeapDumpTimeout  = 120 * time.Second
	defaultHeapDumpCooldown = 10 * time.Minute
)

type heapDumpTask struct {
	pm         *processM
	trigger    string
	tags       []string
	detectedAt time.Time
}

var runHeapDumpCommand = func(ctx context.Context, jmapPath string, outputPath string, pid int32) (string, string, error) {
	args := []string{
		"-dump:format=b,file=" + outputPath,
		strconv.Itoa(int(pid)),
	}
	cmd := exec.CommandContext(ctx, jmapPath, args...) //nolint:gosec

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()
	return stdout.String(), stderr.String(), err
}

func (c *Config) heapDumpTimeout() time.Duration {
	if c == nil || c.HeapDumpTimeout == "" {
		return defaultHeapDumpTimeout
	}
	d, err := time.ParseDuration(c.HeapDumpTimeout)
	if err != nil || d <= 0 {
		return defaultHeapDumpTimeout
	}
	return d
}

func (c *Config) heapDumpCooldown() time.Duration {
	if c == nil || c.HeapDumpCooldown == "" {
		return defaultHeapDumpCooldown
	}
	d, err := time.ParseDuration(c.HeapDumpCooldown)
	if err != nil || d <= 0 {
		return defaultHeapDumpCooldown
	}
	return d
}

func (c *Config) heapDumpEnabledForProcess(p *Process) bool {
	if c == nil || !c.HeapDumpEnabled || p == nil {
		return false
	}
	if p.Language != "" && !strings.EqualFold(p.Language, "java") {
		return false
	}
	if p.HeapDumpOnMemoryEmergency == nil {
		return true
	}
	return *p.HeapDumpOnMemoryEmergency
}

func (m *monitor) enqueueHeapDumpIfNeeded(pm *processM, trigger string, tags []string, detectedAt time.Time) {
	if m == nil || m.config == nil || pm == nil || pm.configProcess == nil {
		return
	}
	if !m.config.heapDumpEnabledForProcess(pm.configProcess) {
		return
	}
	if pm.inHeapDumpCooldown(m.config.heapDumpCooldown()) {
		return
	}
	pm.markHeapDumpTriggered(detectedAt)

	task := &heapDumpTask{
		pm:         pm,
		trigger:    trigger,
		tags:       append([]string(nil), tags...),
		detectedAt: detectedAt,
	}
	select {
	case m.heapDumpChan <- task:
	default:
		log.Warnf("heap dump task queue full, run asynchronously, pid=%d service=%s", pm.Pid, pm.configProcess.Service)
		go m.runHeapDumpTask(task)
	}
}

func (m *monitor) handleHeapDumpTask(task *heapDumpTask) {
	if m == nil || m.config == nil || task == nil || task.pm == nil || task.pm.configProcess == nil {
		return
	}

	outputPath := renderHeapDumpPath(m.config, task.pm, task.tags, task.detectedAt)
	if outputPath == "" {
		log.Errorf("heap dump output path is empty, pid=%d", task.pm.Pid)
		return
	}
	if err := os.MkdirAll(filepath.Dir(outputPath), 0o755); err != nil {
		m.uploadHeapDumpFailure(task, outputPath, fmt.Errorf("create heap dump dir: %w", err))
		return
	}

	ctx, cancel := context.WithTimeout(context.Background(), m.config.heapDumpTimeout())
	defer cancel()

	jmapPath := m.config.HeapDumpJMapPath
	if jmapPath == "" {
		jmapPath = "jmap"
	}
	log.Infof("start heap dump, pid=%d service=%s output=%s trigger=%s", task.pm.Pid, task.pm.configProcess.Service, outputPath, task.trigger)
	stdout, stderr, err := runHeapDumpCommand(ctx, jmapPath, outputPath, task.pm.Pid)
	if err != nil {
		m.uploadHeapDumpFailure(task, outputPath, fmt.Errorf("jmap failed: %w stdout=%s stderr=%s", err, stdout, stderr))
		return
	}

	stat, err := os.Stat(outputPath)
	if err != nil {
		m.uploadHeapDumpFailure(task, outputPath, fmt.Errorf("stat heap dump: %w", err))
		return
	}

	summary := &hprofSummary{
		Service:        task.pm.configProcess.Service,
		PID:            task.pm.Pid,
		ProcessName:    task.pm.Name,
		DetectedAt:     task.detectedAt,
		HProfPath:      outputPath,
		HProfSizeBytes: stat.Size(),
		HProfModTime:   stat.ModTime(),
		MatchedBy:      task.trigger,
		SummaryText: fmt.Sprintf(
			"heap dump generated by Flameshot memory emergency trigger at %s (%d bytes)",
			outputPath, stat.Size(),
		),
	}
	uploadHProfForSummary(context.Background(), m.config, summary, task.tags)
	if err := uploadOOMSummaryLog(summary, m.config.DataKitAddr, task.tags); err != nil {
		log.Errorf("upload heap dump summary failed: %v", err)
		return
	}
	log.Infof("heap dump generated and reported, pid=%d service=%s output=%s", task.pm.Pid, task.pm.configProcess.Service, outputPath)
}

func (m *monitor) uploadHeapDumpFailure(task *heapDumpTask, outputPath string, err error) {
	if m == nil || m.config == nil || task == nil || task.pm == nil || task.pm.configProcess == nil || err == nil {
		return
	}
	log.Errorf("heap dump failed, pid=%d service=%s output=%s err=%v", task.pm.Pid, task.pm.configProcess.Service, outputPath, err)
	summary := &hprofSummary{
		Service:           task.pm.configProcess.Service,
		PID:               task.pm.Pid,
		ProcessName:       task.pm.Name,
		DetectedAt:        task.detectedAt,
		HProfPath:         outputPath,
		MatchedBy:         task.trigger,
		SummaryText:       fmt.Sprintf("heap dump failed by Flameshot memory emergency trigger: %v", err),
		HProfUploadStatus: "failed",
		HProfUploadError:  err.Error(),
	}
	if uploadErr := uploadOOMSummaryLog(summary, m.config.DataKitAddr, task.tags); uploadErr != nil {
		log.Errorf("upload heap dump failure summary failed: %v", uploadErr)
	}
}

func renderHeapDumpPath(cfg *Config, pm *processM, tags []string, detectedAt time.Time) string {
	if cfg == nil || pm == nil || pm.configProcess == nil {
		return ""
	}
	template := cfg.HeapDumpPathTemplate
	if template == "" {
		template = "{profiling_path}/dumps/{service}_{pod_name}_{pid}_{timestamp}.hprof"
	}
	ctx := buildHProfTemplateContext(pm.configProcess.Service, pm.Pid, "", cfg.ProfilingPath, tags, detectedAt)
	ctx.Filename = fmt.Sprintf("%s_%d_%s.hprof", pm.configProcess.Service, pm.Pid, ctx.Timestamp)
	path := renderHProfTemplate(template, ctx)
	return filepath.Clean(path)
}
